    ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
    serializer.writeObject(testString, outputStream);
    outputStream.flush();
    outputStream.close();
    String result = outputStream.toString(UTF_8.name());
    assertNotNull(result);
